from PIL import Image
import os


IMAGE_EXTENSIONS = (".png", ".jpg", ".jpeg", ".bmp")


def rgb888_to_rgb565(r, g, b):
    r5 = r >> 3
    g6 = g >> 2
    b5 = b >> 3

    return (r5 << 11) | (g6 << 5) | b5


def image_name_to_c_name(filename):
    """
    把文件名转成合法的 C 变量名
    例如：
    button-ok.png -> button_ok
    1-test.png    -> img_1_test
    """
    name = os.path.splitext(filename)[0]

    result = ""

    for ch in name:
        if ch.isalnum():
            result += ch
        else:
            result += "_"

    if result[0].isdigit():
        result = "img_" + result

    return result


def convert_folder_to_header(image_folder, output_header):
    image_files = []

    # 找出文件夹内所有图片
    for filename in os.listdir(image_folder):
        if filename.lower().endswith(IMAGE_EXTENSIONS):
            image_files.append(filename)

    # 排序，保证每次生成顺序稳定
    image_files.sort()

    # "w" 模式会直接覆盖原来的 h 文件
    with open(output_header, "w", encoding="utf-8") as f:

        f.write("#pragma once\n")
        f.write("#include <stdint.h>\n\n")

        f.write("/*\n")
        f.write(" * Auto generated by image_to_array.py\n")
        f.write(" * Do not edit manually.\n")
        f.write(" */\n\n")

        for filename in image_files:

            image_path = os.path.join(image_folder, filename)

            image = Image.open(image_path).convert("RGB")

            width, height = image.size

            array_name = image_name_to_c_name(filename)

            upper_name = array_name.upper()

            print(
                f"转换: {filename} "
                f"-> {array_name} "
                f"({width}x{height})"
            )

            # ==========================
            # 宽高
            # ==========================

            f.write(f"#define {upper_name}_WIDTH  {width}\n")
            f.write(f"#define {upper_name}_HEIGHT {height}\n\n")

            # ==========================
            # 像素数组
            # ==========================

            f.write(
                f"static const uint16_t "
                f"{array_name}[{width * height}] = {{\n"
            )

            for y in range(height):

                f.write("    ")

                for x in range(width):

                    r, g, b = image.getpixel((x, y))

                    rgb565 = rgb888_to_rgb565(r, g, b)

                    index = y * width + x

                    f.write(f"0x{rgb565:04X}")

                    if index != width * height - 1:
                        f.write(", ")

                f.write("\n")

            f.write("};\n\n")

    print()
    print(f"共转换 {len(image_files)} 张图片")
    print(f"输出文件: {output_header}")


if __name__ == "__main__":

    IMAGE_FOLDER = r"C:\Users\memory\Desktop\EdgeLink\edgenode\ThirdParty/tools/pitures"

    OUTPUT_HEADER = (
    r"C:\Users\memory\Desktop\EdgeLink\edgenode\ThirdParty\tools\C"
    r"\hmi_widgets_generated.h"
)

    convert_folder_to_header(
        IMAGE_FOLDER,
        OUTPUT_HEADER
    )